INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(728313, 77670, 1009, '<td valign="top">Could use some work on the sharpness, but otherwise a cute and applicable photo. Good job...</td>', 'Could use some work on the sharpness, but otherwise a cute and applicable photo. Good job...', '2004-05-19 23:49:53.000000', NULL, 1),
