(735918, 77006, 19121, '<td valign="top">I hope it''s not true... Good picture though...</td>', 'I hope it''s not true... Good picture though...', '2004-05-25 21:50:48.000000', NULL, 1),
(735920, 77289, 4285, '<td valign="top">Composition: Subject Placement, Cropping, Background (20% Weight):	6<br/>Technical: Focus, Exposure, Lighting, Processing (20% Weight):	5<br/>Appeal: Is it Interesting, Motivating, Etc. (30% Weight):	6<br/>How well does it meet the challenge (30% Weight):	8<br/>Total  Rating (Rounded)	6<br/></td>', 'Composition: Subject Placement, Cropping, Background (20% Weight):	6Technical: Focus, Exposure, Lighting, Processing (20% Weight):	5Appeal: Is it Interesting, Motivating, Etc. (30% Weight):	6How well does it meet the challenge (30% Weight):	8Total  Rating (Rounded)	6', '2004-05-25 21:51:08.000000', NULL, 1),
